// ④ 의미 있는 이벤트인가 판단

const tweet = $input.item.json;
const text = tweet.full_text || tweet.text || '';

// 스팸 패턴
const spamPatterns = [
  /giveaway/i,
  /follow.*win/i,
  /click.*link/i,
  /bet.*now/i
];

for (const pattern of spamPatterns) {
  if (pattern.test(text)) {
    return []; // 버림
  }
}

// 의미 있는 패턴
const meaningfulPatterns = [
  /\b(OUT|INACTIVE|RULED OUT)\b.*\b(tonight|today|vs|@)\b/i,
  /\b(QUESTIONABLE|DOUBTFUL|PROBABLE)\b.*\(.*\)/i,  // 부상 원인 포함
  /\bCrew Chief\b.*\bReferee/i,
  /\bStarting (lineup|five)\b/i
];

for (const pattern of meaningfulPatterns) {
  if (pattern.test(text)) {
    return [$input.item]; // 통과
  }
}

// 기본: 버림
return [];

