// Grok 응답 파싱 및 정리

const response = $input.item.json;
const content = response.choices[0].message.content;

// JSON 추출 (코드 블록 제거)
let jsonContent = content;
if (content.includes('```json')) {
  jsonContent = content.split('```json')[1].split('```')[0].trim();
} else if (content.includes('```')) {
  jsonContent = content.split('```')[1].split('```')[0].trim();
}

const event = JSON.parse(jsonContent);

// 메타데이터 추가
event.tweet_id = $node["X Watch - Official Accounts"].json.id_str;
event.tweet_created_at = $node["X Watch - Official Accounts"].json.created_at;
event.tweet_author = $node["X Watch - Official Accounts"].json.user.screen_name;
event.processed_at = new Date().toISOString();

return { json: event };

